"""Build portrait findings and derived HTML from final offline calculation outputs."""
import pathlib,json,datetime,shutil
R=pathlib.Path(__file__).parent;C=R.parent.parent;W=C.parent.parent;now=datetime.datetime.now(datetime.UTC).isoformat().replace('+00:00','Z');data=json.loads((R/'results.json').read_text())
source='https://services8.arcgis.com/JFYbogndXme7ddg8/arcgis/rest/services/CA_Cons_Areas_parentlyr_Merge_ecofix/FeatureServer/55'
for t in ['carmel','monterey-county']:
 x=data[t];f=json.loads((C/t/'findings/biodiversity-loss.json').read_text())[0]
 f.update(value=x['protected_share_pct'],year=2024,level_pct=x['level_pct'],source='Derived from CNRA CA Nature 30x30 Conserved Areas, Terrestrial (2024 snapshot), official boundaries and Census 2026 land/water faces',source_url=source,evidence={'snapshot_path':'evidence/biodiversity-loss-derived-2024.png','captured_at':now})
 f['scoring']['inputs']['value']=x['protected_share_pct'];f['scoring']['worked_math']=f"protected share = {x['protected_m2']:.9f} / {x['land_m2']:.9f} × 100 = {x['protected_share_pct']:.12f}%; level_pct = (30 − {x['protected_share_pct']:.12f}) / 30 × 100 = +{x['level_pct']:.12f}"
 f['notes']=("Derived 2024 mapped inventory, not a jurisdiction-published total or a complete legal parcel audit. Tier 1 searched: City park/GIS and County GIS/Williamson Act sources did not supply complete recent durable conservation shares. Tier 2 official CNRA dataset accepted. Filter Release_Year=2024 and reGAP IN (1,2), matching that snapshot's DefaultSelection=Yes; county category-statistics query confirms GAP3/4 are No. The 2024 publisher methodology uniformly assigns operative Conservation Units based on >80% GAP-code overlap (or combined GAP1/2 overlap), so mapped units are a generalized conservation inventory, not exact parcel-level legal status. Older 2023 records sharing this service are explicitly excluded. More recent 2026 data was investigated and rejected for this derivation: its geometries mix GAP classes, with partial conserved-acre fields and qualifying portions inside GAP3/4 units; precise jurisdiction clipping would need their underlying subgeometry. No partial 2026 fractions are imputed to city land. " +
 ("Jurisdiction boundary: official Monterey County LAFCO Incorporated Cities_2, CITY=CARMEL BY-THE-SEA, retrieved 2026-10-23; no effective boundary date supplied. Carmel Valley and other unincorporated Carmel land are excluded. " if t=='carmel' else "Jurisdiction: all incorporated and unincorporated Monterey County, current Census TIGERweb GEOID 06053, retrieved 2026-10-23. ")+
 "The 2024 conservation inventory is evaluated against current retrieved boundaries and Census 2026 perennial-water faces; it is not a claim about conservation gains through 2026. Exclude LWFLAG=P water (ocean, bays, lakes, other perennial water) from numerator and denominator; retain intermittent water under Census land convention. WGS84 GeoJSON and NAD83 Census water are transformed to California Albers EPSG:3310 using the null NAD83/WGS84 geographic transform at this precision. Union protected polygons before measuring clipped area; overlaps count once. "+
 f"Numerator={x['protected_m2']:.9f} m² ({x['protected_acres']:.9f} acres), denominator={x['land_m2']:.9f} m² ({x['land_acres']:.9f} acres). 2,125 candidate features downloaded completely; 1,316 belong to Release_Year=2024; {x['intersecting_feature_count']} intersect jurisdiction land. "+
 (f"Census place-boundary sensitivity gives {data['carmel-census-crosscheck']['protected_share_pct']:.9f}%; local LAFCO boundary governs the finding. " if t=='carmel' else "Union removes 754.581983 m² of overlapping protected polygons. Land denominator differs from Census AREALAND=8,499,610,214 m² by 768 m² (0.000009%), consistent with projection/rounding. ")+
 "Source uncertainty includes generalized boundaries and omitted/misclassified conservation; confidence medium. All raw query URLs/hashes, compressed polygons, per-feature areas and offline script are archived in calculations/biodiversity-loss/. Primary exhibit is labelled our derived calculation; official dataset, methodology, boundary and water-definition captures are supplemental.")
 (C/t/'findings/biodiversity-loss.json').write_text(json.dumps([f],indent=2)+'\n')
 base=W/'apps/web/public/evidence'/t/'evidence';name='Carmel-by-the-Sea city limits' if t=='carmel' else 'All Monterey County'
 body=f'''<!doctype html><meta charset="utf-8"><title>Derived protected land share — {name}</title><style>body{{font:18px system-ui;margin:48px;max-width:1100px;color:#18232e}}h1{{font-size:30px}}table{{border-collapse:collapse;width:100%}}td,th{{border:1px solid #bcc7cf;padding:12px;text-align:left}}.label{{background:#e5edf4;padding:16px}}p{{line-height:1.5}}small{{font-size:14px;overflow-wrap:anywhere}}</style><h1>{name}: protected land share</h1><p class="label"><b>Our derived GIS calculation — not a table published by CNRA or the jurisdiction.</b><br>Conservation snapshot: 2024. Boundaries/water: current retrieved / Census 2026.<br>Calculated: {now}</p><table><tr><th>Measure</th><th>Result</th></tr><tr><td>Mapped protected land (GAP 1/2), clipped and unioned</td><td>{x['protected_m2']:,.6f} m² / {x['protected_acres']:,.6f} acres</td></tr><tr><td>Jurisdiction land area, perennial water removed</td><td>{x['land_m2']:,.6f} m² / {x['land_acres']:,.6f} acres</td></tr><tr><td>Share = protected / land × 100</td><td><b>{x['protected_share_pct']:.9f}%</b></td></tr><tr><td>Target and scored shortfall</td><td>30%; +{x['level_pct']:.9f}%</td></tr></table><p>Filter: Release_Year=2024 and reGAP 1/2. The 2024 dataset assigns generalized Conservation Units uniformly based on >80% overlap, following its published method. This mapped inventory can omit or misclassify legal protection.</p><p>Equal-area projection: EPSG:3310. Water: Census 2026 LWFLAG=P; intermittent-water faces retain Census land status. All polygons clipped to jurisdiction land and unioned before measurement.</p><p>The 2026 layer was rejected for this calculation because its unit geometries mix conservation classes; partial conserved-acre fields do not locate protected portions for exact city clipping.</p><p>{'Official local LAFCO boundary; city limits only. Census alternative boundary sensitivity: '+format(data['carmel-census-crosscheck']['protected_share_pct'],'.9f')+'%.' if t=='carmel' else 'All cities and unincorporated county included. Union removes 754.581983 m² overlap. Land denominator matches Census AREALAND within 0.000009%.'}</p><small>Primary dataset: {source}<br>Reproduction: calculations/biodiversity-loss/calculate.py. Inputs: raw-manifest.json. This measures the 2024 mapped conservation inventory against the retrieved boundaries, not conservation gains through 2026.</small>'''
 (base/'biodiversity-loss-derived-2024.html').write_text(body)
 p=C/t/'evidence-additions/biodiversity-loss.json';e=json.loads(p.read_text());e['protected-land-share'][0]={'label':'Official 2024 conservation-unit layer metadata','source_url':source,'snapshot_path':'evidence/'+('1aef9d6e15f16845' if t=='carmel' else 'b40c23b60c4debc3')+'.png'};e['protected-land-share']=[a for a in e['protected-land-share'] if a['label'] != 'Official 2024 uniform Conservation Unit assignment methodology'];e['protected-land-share'].append({'label':'Official 2024 uniform Conservation Unit assignment methodology','source_url':'https://www.arcgis.com/sharing/rest/content/items/6dc5f19f7f6c4413a3bac944d1f9a173?f=pjson','snapshot_path':'evidence/a813f5b3406143fa.png'});p.write_text(json.dumps(e,indent=2)+'\n')
for p in (W/'apps/web/public/evidence/carmel/evidence').glob('a813f5b3406143fa.*'):shutil.copyfile(p,W/'apps/web/public/evidence/monterey-county/evidence'/p.name)
